  @override
  Widget build(BuildContext context) {
    final currentRoute = ModalRoute.of(context)?.settings.name ?? '';
    return SafeArea(
      minimum: const EdgeInsets.only(bottom: 16),
      child: Container(
        height: 84,
        margin: const EdgeInsets.symmetric(horizontal: 16),
        padding: const EdgeInsets.symmetric(horizontal: 8),
        decoration: BoxDecoration(
          color: const Color(0x99231B12),
          border: Border.all(color: HeritageColors.orange.withOpacity(0.20)),
          borderRadius: BorderRadius.circular(42),
          boxShadow: const [BoxShadow(color: Color(0x8C000000), blurRadius: 24, offset: Offset(0, 12))],
        ),
        child: Row(
          children: List.generate(_items.length, (index) {
            final item = _items[index];
            final selected = _isSelected(currentRoute, item.route);
            return Expanded(
              child: InkWell(
                onTap: () => Navigator.of(context).pushReplacementNamed(item.route),
                borderRadius: BorderRadius.circular(30),
                child: Opacity(
                  opacity: selected ? 1 : 0.40,
                  child: Column(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      SizedBox(
                        width: 22,
                        height: 22,
                        child: SvgPicture.string(
                          '<svg viewBox="${item.viewBox}" xmlns="http://www.w3.org/2000/svg"><path d="${item.path}" fill="${selected ? '#F4A261' : '#FFFFFF'}"/></svg>',
                        ),
                      ),
                      const SizedBox(height: 4),
                      Text(
                        item.label.toUpperCase(),
                        style: TextStyle(
                          fontSize: 10,
                          height: 1.5,
                          fontWeight: FontWeight.bold,
                          color: selected ? HeritageColors.orange : Colors.white,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            );
          }),
        ),
      ),
    );
  }

  bool _isSelected(String currentRoute, String route) {
    if (route == '/archive') {
      return currentRoute.startsWith('/archive') && currentRoute != '/archive/shingo';
    }
    if (route == '/quests') {
      return currentRoute.startsWith('/quests');
    }
    return currentRoute == route;
  }
}

class _NavItem {
  const _NavItem({required this.label, required this.route, required this.viewBox, required this.path});

  final String label;
  final String route;
  final String viewBox;
  final String path;
}
